import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Ajustar a saturação leva só alguns minutos. Você envia a foto, arrasta um controle, confere as cores e baixa a versão mais viva.</p>\n<p>Este passo a passo cobre o processo inteiro. Você vai ver o controle, as predefinições rápidas, os tons de pele e as configurações de exportação que mantêm as cores naturais.</p>\n<p>No final, você vai conseguir corrigir uma paisagem sem graça, suavizar uma foto berrante ou transformar um retrato colorido num preto e branco limpo em qualquer dispositivo. Guarde a foto original até conferir o resultado.</p>\n<h2 id=\"before-you-start\">Antes de começar: avalie as cores</h2>\n<p>Olhe a foto antes de abrir a ferramenta. As cores estão sem graça, vivas ou berrantes? A resposta diz para que direção mover o controle.</p>\n<p>Uma foto sem graça precisa de um reforço positivo de 10 a 25 por cento. Uma berrante precisa de um movimento negativo para suavizar as cores de volta ao natural.</p>\n<p>Confira se a foto também está escura ou chapada demais. Uma foto sem graça e escura precisa de brilho primeiro, porque só a saturação não corrige o nível.</p>\n<p>Abra o <a href=\"/pt/ajustar-saturacao-da-imagem/\">Ajustar saturação da foto</a> no seu navegador. Tudo roda localmente, então sua foto nunca é enviada para um servidor.</p>\n<h2 id=\"step-by-step\">Ajuste a saturação em cinco passos</h2>\n<p>O processo é o mesmo para uma foto, uma captura de tela ou uma imagem digitalizada. Envie, ajuste, confira as cores, exporte e confira o download.</p>\n<p>Leve o controle com calma. Movimentos pequenos fazem uma grande diferença, e a prévia mostra exatamente quando as cores ficam certas.</p>\n<ol>\n<li>Envie sua imagem arrastando-a para a área de envio, escolhendo-a no seu dispositivo ou colando uma captura de tela com Ctrl+V.</li>\n<li>Arraste o controle Nível de saturação para a direita para reforçar as cores ou para a esquerda para suavizá-las, observando a prévia ao vivo.</li>\n<li>Teste um ajuste pronto, como Suavizado, Preto e branco ou Hiper, para ver o resultado em um clique, e depois afine com o controle.</li>\n<li>Confira os tons de pele, a folhagem e o céu em tamanho real para confirmar que nenhuma cor parece artificial.</li>\n<li>Escolha o formato e a qualidade de exportação e clique em Baixar para salvar a imagem ajustada.</li>\n</ol>\n<p>Abra o arquivo baixado uma vez antes de usá-lo. Confirme que as cores parecem naturais e vivas sem virar neon ou laranja.</p>\n<h2 id=\"using-the-slider\">Como usar o controle de saturação</h2>\n<p>O controle vai de menos 100 a mais 100 por cento, com zero significando nenhuma mudança. Mover para a direita reforça as cores, e mover para a esquerda drena elas.</p>\n<p>Arraste devagar e observe a prévia. A atualização ao vivo mostra exatamente como as cores reagem, então você pode parar no ponto em que a foto parece natural.</p>\n<p>Movimentos pequenos são melhores que os grandes. Uma mudança de 10 a 25 por cento costuma bastar, e movimentos maiores deixam as cores artificiais rapidinho.</p>\n<p>A ferramenta mostra sua foto em mais 25 por cento logo depois do envio. Esse ponto de partida já dá uma ideia imediata de como fica um reforço moderado de saturação.</p>\n<h2 id=\"using-quick-presets\">Como usar as predefinições rápidas</h2>\n<p>A ferramenta inclui predefinições de um clique que aplicam valores comuns de saturação na hora. São um jeito rápido de testar visuais diferentes sem arrastar o controle.</p>\n<p>Suavizado, em menos 40 por cento, amacia as cores para um visual calmo e elegante. Preto e branco, em menos 100 por cento, remove toda a cor para uma imagem preto e branco.</p>\n<p>Hiper, em mais 90 por cento, empurra as cores até o limite. Ele combina com cartazes e gráficos estilizados, mas raramente combina com fotografia natural.</p>\n<p>Clique numa predefinição e olhe a prévia. Se o resultado estiver perto, mas não exato, ajuste com o controle a partir daquele ponto.</p>\n<h2 id=\"boosting-a-dull-photo\">Como dar vida a uma foto sem graça</h2>\n<p>Envie a foto sem graça e arraste o controle para mais 20 por cento. Confira a prévia: as cores devem parecer mais ricas, com verdes mais profundos e céus mais azuis, sem parecer falsas.</p>\n<p>Se a foto continuar sem graça, aumente o controle em passos pequenos de 5 por cento. Cada passo adiciona um pouco mais de vivacidade, e a prévia mostra quando parar.</p>\n<p>Observe a folhagem enquanto ajusta. Grama e folhas viram neon primeiro, e uma paisagem com campos verdes brilhantes parece artificial.</p>\n<p>Se a foto parecer berrante depois do reforço, reduza o controle em 5 por cento. Uma pequena redução costuma restaurar o visual natural sem perder a vivacidade.</p>\n<h2 id=\"muting-a-harsh-photo\">Como suavizar uma foto dura e berrante</h2>\n<p>Arraste o controle para a esquerda para uma foto cujas cores estão fortes demais. Valores negativos, como menos 20 ou menos 40 por cento, suavizam a paleta num visual mais calmo.</p>\n<p>Confira a pele enquanto suaviza. O rosto deve parecer natural e suave, não cinza e sem vida, então pare antes que as cores sumam por completo.</p>\n<p>Suavizar combina com casamentos, retratos e arte, onde uma paleta gentil parece elegante. Uma foto suave, com cores macias, parece refinada, enquanto uma berrante parece alta demais.</p>\n<p>Para um visual totalmente dessaturado, use a predefinição Preto e branco, em menos 100 por cento. A imagem vira preto e branco, o que combina com cenas dramáticas e retratos atemporais.</p>\n<h2 id=\"converting-to-grayscale\">Como converter para preto e branco em um clique</h2>\n<p>Clique na predefinição Preto e branco para remover toda a cor da foto num só passo. A imagem vira preto e branco, com só brilho e contraste para carregá-la.</p>\n<p>Preto e branco combina com cenas dramáticas, arquitetura e fotografia de rua, onde forma e luz importam mais que cor. Também combina com retratos de expressão forte.</p>\n<p>Depois de converter, confira o contraste. Uma foto preto e branco muitas vezes precisa de um pequeno reforço de contraste, porque a cor carregava parte da profundidade que agora sumiu.</p>\n<p>Exporte fotos preto e branco em JPG com qualidade alta, ou em PNG para o resultado mais nítido. O formato importa menos que o contraste, que define o visual preto e branco.</p>\n<h2 id=\"fixing-skin-tones\">Como corrigir tons de pele</h2>\n<p>A pele é o mais difícil de saturar corretamente. Um pequeno reforço pode deixar um retrato saudável, mas um grande deixa a pele laranja, vermelha ou amarela.</p>\n<p>Comece com um pequeno aumento, de 10 a 15 por cento, para retratos. Confira o rosto: a pele deve parecer quente e natural, não como se a pessoa tivesse passado tempo demais no sol.</p>\n<p>Observe as bochechas e a testa, que mostram a saturação excessiva primeiro. Um rosto com bochechas laranja e testa amarela foi levado longe demais.</p>\n<p>Se a pele parecer laranja depois do reforço, reduza o controle em 5 por cento e confira de novo. Pequenas reduções costumam restaurar o tom natural sem perder o brilho saudável.</p>\n<h2 id=\"previewing\">Prévia antes de baixar</h2>\n<p>Confira sempre a prévia antes de baixar. Veja se as cores parecem naturais, se nenhuma área virou neon e se os tons de pele estão quentes em vez de laranja.</p>\n<p>Dê zoom na folhagem, no céu e na pele em tamanho real. Essas áreas mostram a saturação excessiva primeiro, e uma prévia pequena pode esconder o problema.</p>\n<p>Confira a foto numa segunda tela, se puder. As cores parecem diferentes em telas diferentes, e uma segunda checagem pega surpresas antes de você compartilhar a imagem.</p>\n<p>Se alguma cor parecer artificial, reduza o controle em 5 por cento e confira de novo. Pequenas reduções costumam restaurar o visual natural sem perder a vivacidade.</p>\n<h2 id=\"choosing-export-format\">Como escolher o formato de exportação</h2>\n<p>Escolha JPG para fotos que você planeja compartilhar. Ele mantém os arquivos pequenos e funciona em todo lugar, e uma qualidade alta mantém as cores limpas.</p>\n<p>Escolha PNG para gráficos e adesivos com transparência. O PNG não tem perda, então as cores ficam exatas, e ele preserva áreas vazadas.</p>\n<p>Escolha WebP quando quiser arquivos pequenos com boa qualidade. Ele funciona bem para imagens de web, embora alguns sistemas mais antigos ainda rejeitem o formato.</p>\n<p>Lembre que o controle de qualidade some para PNG, porque o PNG não tem perda e não tem ajuste de qualidade. Isso é comportamento normal, não um problema da ferramenta.</p>\n<h2 id=\"adjusting-on-mobile\">Como ajustar a saturação no celular ou no tablet</h2>\n<p>A ferramenta funciona em telas de toque, então dá para corrigir uma foto sem graça no próprio celular que a tirou. Envie da sua galeria, arraste o controle com o dedo e baixe o resultado.</p>\n<p>Arrastar um controle com o dedo é menos preciso que com o mouse. Use as predefinições rápidas para valores exatos e depois ajuste com arrastes pequenos.</p>\n<p>Confira a prévia em tamanho real antes de baixar. Uma mudança de saturação que parece boa na tela pequena do celular pode ficar forte demais quando vista no computador.</p>\n<p>Os arquivos baixados vão para a sua pasta de downloads. De lá, você pode compartilhar a foto editada direto num aplicativo de conversa, num e-mail ou num post de rede social.</p>\n<h2 id=\"troubleshooting\">Solução de problemas comuns de saturação</h2>\n<p>Se a foto parecer berrante, o controle está alto demais. Reduza em passos pequenos até a grama, o céu e a pele parecerem naturais de novo.</p>\n<p>Se a foto continuar sem graça depois do reforço, a original pode ser chapada demais para salvar. Uma foto tirada através de nevoeiro espesso não ganha cor que nunca foi capturada.</p>\n<p>Se a pele parecer laranja, reduza a saturação e confira o rosto em tamanho real. Uma pequena redução geralmente restaura o tom natural.</p>\n<p>Se a prévia parecer diferente do download, confira o formato e a qualidade de exportação. Uma qualidade JPG baixa pode mudar as cores levemente, principalmente em áreas claras.</p>\n<h2 id=\"saturation-plus-contrast\">Saturação mais contraste: a dupla comum</h2>\n<p>Uma foto sem graça e chapada precisa de saturação e contraste juntos. Reforce as cores primeiro e depois adicione contraste para restaurar a profundidade.</p>\n<p>Use o <a href=\"/pt/ajustar-contraste-da-imagem/\">ajustar o contraste da foto</a> depois de saturar, quando a imagem parecer viva, mas ainda chapada. Um pequeno reforço de contraste traz de volta as sombras e os realces.</p>\n<p>Faça os passos em ordem: saturação primeiro, depois contraste. Inverter pode deixar a mudança de cor mais difícil de avaliar, porque a imagem continua chapada.</p>\n<p>Confira as cores depois de cada passo. Um reforço de contraste deixa as cores mais ricas também, então a saturação pode precisar de uma pequena redução depois.</p>\n<h2 id=\"saturation-for-social\">Saturação para redes sociais</h2>\n<p>Os feeds de redes sociais preferem fotos vivas e claras. Uma foto sem graça é ignorada na rolagem, enquanto uma bem saturada faz parar o dedo e ganhar um segundo olhar.</p>\n<p>Reforce fotos de redes sociais um pouco mais do que faria para impressão. As telas variam em cor, e uma foto que parece boa no seu celular pode parecer sem graça no de outra pessoa.</p>\n<p>Mantenha o reforço natural. Uma foto levada longe demais parece artificial, e os seguidores percebem quando as cores não combinam com a cena.</p>\n<p>Teste a foto saturada no tamanho do feed antes de postar. Uma foto que parece boa em tamanho real pode ficar sem graça ou berrante demais numa prévia pequena, então confira antes de publicar.</p>\n<h2 id=\"saving-settings\">Como guardar seus ajustes para a próxima vez</h2>\n<p>Anote o valor de saturação que funcionou para um conjunto de fotos parecidas. Uma anotação curta, como paisagens mais 20 por cento, evita adivinhar na próxima vez.</p>\n<p>Para um lote de fotos tiradas com a mesma luz, use o mesmo valor para todas. Uma cor consistente num conjunto parece profissional, enquanto valores misturados parecem aleatórios.</p>\n<p>Guarde os arquivos originais. Um valor de saturação que funciona para uma foto pode não servir para outra, e a original permite testar outro nível sem dano extra.</p>\n<p>Revise suas anotações de vez em quando. Conforme sua câmera e sua iluminação melhoram, os valores de saturação de que você precisa vão mudar, e anotações antigas podem enganar.</p>\n<h2 id=\"quick-tips\">Dicas rápidas para uma saturação melhor</h2>\n<p>Ajuste em passos pequenos. Uma mudança de 5 por cento por vez dá controle, enquanto um salto grande pode passar do valor certo antes de você perceber.</p>\n<p>Confira a pele, não só a paisagem. Um reforço de paisagem que parece bom na grama pode deixar as pessoas da foto laranja.</p>\n<p>Use as predefinições como ponto de partida. Uma predefinição dá um teste rápido, e o controle permite ajustar a partir daí.</p>\n<p>Guarde a foto original sem edições. Depois que uma mudança de saturação é aplicada numa exportação, não dá para desfazê-la a partir daquele arquivo.</p>\n<h2 id=\"saturation-for-sunset\">Como ajustar a saturação de uma foto de pôr do sol</h2>\n<p>Fotos de pôr do sol já são coloridas, então precisam só de um pequeno reforço. Um aumento de saturação de 10 a 15 por cento aprofunda os laranjas e os rosas sem deixar o céu pintado.</p>\n<p>Observe o gradiente do céu enquanto reforça. Um céu de pôr do sol deve desvanecer suavemente de laranja para rosa e azul, e um reforço forte pode transformar esse gradiente em blocos chapados de cor.</p>\n<p>Confira o primeiro plano depois do reforço. Um primeiro plano escuro com cores reforçadas pode parecer turvo, então clareie ele levemente primeiro se o pôr do sol for o assunto principal.</p>\n<p>Para um pôr do sol sobre a água, um reforço moderado realça o reflexo sem deixá-lo berrante. A água deve espelhar o céu, não competir com ele.</p>\n<p>Para a comparação, leia <a href=\"/pt/blog/saturacao-vs-vibrancia/\">Saturação ou vibrância: qual a diferença?</a>. Para a visão geral, veja <a href=\"/pt/blog/como-deixar-foto-mais-colorida/\">Como deixar a foto mais colorida: guia de saturação</a>, e para dar um visual consistente às fotos, experimente a <a href=\"/pt/filtros-de-imagem/\">ferramenta de filtros de foto</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Como reforço a cor de uma foto no celular?","answer":"Abra a ferramenta de ajuste de saturação da foto no navegador do celular, envie a foto da sua galeria e arraste o controle para a direita com o dedo. Use um ajuste pronto para um valor exato, confira os tons de pele e baixe o resultado."},{"question":"Qual valor de saturação devo usar para uma foto de paisagem?","answer":"Comece em mais 20 por cento e confira a folhagem. Paisagens geralmente precisam de 20 a 30 por cento para parecer vivas. Pare antes que a grama vire neon ou o céu pareça pintado, e reduza o controle se as cores parecerem artificiais."},{"question":"Como transformo uma foto colorida em preto e branco?","answer":"Clique na predefinição Preto e branco, que define a saturação em menos 100 por cento e remove toda a cor num só passo. Confira o contraste depois, pois uma foto preto e branco muitas vezes precisa de um pequeno reforço de contraste para substituir a profundidade que a cor carregava."},{"question":"Por que minha foto de comida parece falsa depois de reforçar a saturação?","answer":"O controle está alto demais, o que deixa os vermelhos brilhantes demais e os verdes neon. Comida precisa só de um pequeno reforço, de 10 a 20 por cento. Reduza o controle até o prato parecer fresco e apetitoso em vez de plástico."},{"question":"Devo ajustar a saturação antes ou depois do contraste?","answer":"Saturação primeiro, depois contraste. Reforçar as cores muda como a imagem parece, e o contraste refina a profundidade depois. Confira as cores de novo depois da mudança de contraste, pois ela deixa elas mais ricas também."},{"question":"Dá para desfazer uma mudança de saturação depois de baixar?","answer":"Não a partir do arquivo baixado, pois a mudança é aplicada na exportação. Guarde a foto original para testar outro nível de saturação. Na ferramenta, use a opção de redefinir para voltar a zero antes de baixar."}];
